from scipy.optimize import least_squares
names=['1','x','v','x2','v2','xv','c','s','cx','sx','cv','sv','cx2','sx2','cv2','sv2']
def mk(w):
    c=np.cos(w*t); s=np.sin(w*t)
    return [np.ones_like(t),x,v,x**2,v**2,x*v,c,s,c*x,s*x,c*v,s*v,c*x**2,s*x**2,c*v**2,s*v**2]
def run(sel):
    best=None
    for w0 in np.linspace(0.36,0.42,7):
        cols=lambda w: np.column_stack([mk(w)[i] for i in sel])
        f=lambda p: cols(p[0])@p[1:]-dv_dt
        r=least_squares(f,np.concatenate([[w0],np.zeros(len(sel))]))
        if best is None or r.cost<best.cost: best=r
    return round(np.mean(best.fun**2)/np.var(dv_dt),6), best.x[0].round(5), best.x[1:].round(3)
idx={n:i for i,n in enumerate(names)}
for s in [['1','x','v','c','s','cv','sv'],['1','x','v','v2','c','s','cv','sv'],['1','x','v','x2','v2','xv','c','s','cv','sv'],['1','x','v','v2','c','s','cv','sv','cx','sx']]:
